import { useState } from "react";

export function Expand({
  text = "{{text}}",
  expanded: initialExpanded = {{expanded}},
  lines = {{lines}},
  accent = "{{accent}}",
}) {
  const [expanded, setExpanded] = useState(initialExpanded);
  return (
    <div style={{ width: 320, fontFamily: "system-ui, sans-serif", fontSize: 14, lineHeight: 1.5, color: "#241430" }}>
      <p style={expanded ? {} : { display: "-webkit-box", WebkitBoxOrient: "vertical", WebkitLineClamp: lines, overflow: "hidden" }}>{text}</p>
      <button type="button" aria-expanded={expanded} onClick={() => setExpanded((e) => !e)}
        style={{ marginTop: 8, border: "none", background: "transparent", color: accent, fontWeight: 700, cursor: "pointer", padding: 0, fontSize: 13 }}>
        {expanded ? "Show less" : "Read more"}
      </button>
    </div>
  );
}
